"""Tool-specific collector recipes. Unverified profiles, not blanket tool coverage."""
PROFILES = {}


def rule(path, op, expected, title, cause, steps):
    return dict(path=path, op=op, expected=expected, title=title, cause=cause, steps=steps)


def add(key, name, category, scope, *, command=None, endpoint=None, fields=None,
        rules=(), guidance=(), parser="json", cwd=None, ok=(0,), method="GET", body=None,
        repair=None, health_codes=(200,), local_file=None):
    PROFILES[key] = dict(id=key, name=name, category=category, scope=scope,
        command=command, endpoint=endpoint, fields=fields or {}, rules=list(rules),
        guidance=list(guidance), parser=parser, cwd=cwd, ok=list(ok), method=method,
        body=body, repair=repair, health_codes=list(health_codes), local_file=local_file,
        maturity="implemented-unverified")


def bad(path, values, title, cause, steps):
    return rule(path, "in", values, title, cause, steps)


# 01–05: cloud providers. Explicit account/project selectors, one resource per scan.
add("aws", "AWS", "Cloud", "EC2 instance and system status checks", command=["aws","--profile","$profile","--region","$region","ec2","describe-instance-status","--instance-ids","$resource","--include-all-instances","--output","json"], fields={"instance":"InstanceStatuses.*.InstanceId","state":"InstanceStatuses.*.InstanceState.Name","system":"InstanceStatuses.*.SystemStatus.Status","instance_check":"InstanceStatuses.*.InstanceStatus.Status"}, rules=[bad("state",["stopped","stopping","terminated","shutting-down"],"EC2 is not running","An operator action, shutdown, or lifecycle event may explain the state.",["Inspect CloudTrail and instance lifecycle events","Verify intended state before starting or replacing the instance"]),bad("system",["impaired"],"EC2 system check impaired","Underlying host or AWS networking may be affected.",["Inspect AWS Health and scheduled events","Review recovery options and storage impact before recovery"])],guidance=["This profile covers one EC2 instance, not all AWS services.","Check IAM authorization, region, and instance identity."])
add("azure","Microsoft Azure","Cloud","VM instance view",command=["az","vm","get-instance-view","--subscription","$subscription","--resource-group","$group","--name","$resource","--output","json"],fields={"name":"name","status":"instanceView.statuses.*.code","provisioning":"provisioningState"},rules=[bad("provisioning",["Failed"],"VM provisioning failed","Provisioning, extension, policy, or resource constraints need investigation.",["Review Azure Activity Log and VM extension status","Resolve the reported constraint before another deployment"])],guidance=["PowerState/deallocated is not automatically an incident; compare with intended state."])
add("gcp","Google Cloud","Cloud","Compute Engine instance status",command=["gcloud","compute","instances","describe","$resource","--project","$project","--zone","$zone","--format=json"],fields={"id":"id","name":"name","status":"status","zone":"zone"},rules=[bad("status",["TERMINATED","STOPPING","SUSPENDED"],"Instance is not serving normally","Lifecycle changes or a deliberate stop are possible.",["Check audit logs and serial console through your normal access","Compare actual state with the workload's desired state"])])
add("digitalocean","DigitalOcean","Cloud","Droplet status",command=["doctl","--context","$context","compute","droplet","get","$resource","--output","json"],fields={"id":"*.id","name":"*.name","status":"*.status","region":"*.region.slug"},rules=[rule("status","not_in",["active"],"Droplet is not active","A lifecycle operation, shutdown, or provider issue may be in progress.",["Review droplet actions and provider status","Verify backups before recovery operations"])])
add("oci","Oracle Cloud","Cloud","Compute instance lifecycle",command=["oci","--profile","$profile","--region","$region","compute","instance","get","--instance-id","$resource"],fields={"id":"data.id","state":"data.lifecycle-state","name":"data.display-name"},rules=[bad("state",["STOPPED","STOPPING","TERMINATED","TERMINATING"],"OCI instance is not running","The instance is stopped or transitioning.",["Review OCI work requests and audit events","Confirm intended lifecycle and attached storage before recovery"])])

# 06–10: containers. Inspect state only; never expose Config.Env or health log bodies.
for key,name in (("docker","Docker"),("podman","Podman")):
    prefix = ["docker","--context","$context"] if key == "docker" else ["podman","--connection","$context"]
    add(key,name,"Containers","One container's identity and state",command=prefix+["container","inspect","$resource"],fields={"id":"*.Id","name":"*.Name","state":"*.State.Status","exit_code":"*.State.ExitCode","oom":"*.State.OOMKilled","started":"*.State.StartedAt","health":"*.State.Health.Status"},rules=[bad("state",["exited","dead","stopped","restarting"],"Container is not steadily running","Application exit, missing dependencies, resource limits, or restart loops are possible.",["Inspect exit code and deployment changes","Review container logs locally with secrets redacted","Resolve the cause before approving a restart"]),bad("oom",[True],"Container was killed under memory pressure","The kernel/cgroup memory limit may have been reached.",["Compare memory limits with actual usage","Investigate leaks and workload growth"]),bad("health",["unhealthy"],"Container health check failed","The configured probe failed; startup delay, dependencies, or an application fault may be responsible.",["Inspect the health-check definition and dependency readiness","Validate application health after any restart"])],repair={"id":"restart","command":prefix+["container","restart","--time","10","$resource"],"allowed_field":"state","allowed_values":["exited","dead","stopped","restarting"],"verify_field":"state","verify_values":["running"],"risk":"Interrupts this container; the original fault may recur. No automatic rollback."})
add("containerd","containerd","Containers","Task inventory in one namespace",command=["ctr","--address","$socket","--namespace","$namespace","tasks","list"],parser="tasks",rules=[bad("state",["STOPPED","UNKNOWN"],"containerd task is not running","The task may have exited or lost runtime state.",["Inspect the owning orchestrator and task exit details","Do not manipulate an orchestrator-owned task directly"])],guidance=["A missing task may be expected for an image-only namespace.","Compare task state with your orchestrator before attempting recovery."])
add("compose","Docker Compose","Containers","Services in one explicit Compose project",command=["docker","--context","$context","compose","--project-directory","$directory","--project-name","$project","ps","--all","--format","json"],fields={"service":"*.Service","state":"*.State","health":"*.Health","exit_code":"*.ExitCode","id":"*.ID"},parser="jsonlines",rules=[bad("state",["exited","dead","restarting"],"Compose service is not running steadily","Service startup, dependency, image, or resource configuration may be failing.",["Inspect the affected service's exit code and logs","Validate Compose configuration locally without sharing resolved secrets","Fix the source configuration before redeploying"])])
add("buildah","Buildah","Containers","Working-container state",command=["buildah","inspect","--type","container","$resource"],fields={"name":"Container","id":"ContainerID","image":"FromImageID","process_label":"ProcessLabel"},guidance=["This inspects a working container, not the success of a previous build.","For build failures, inspect the failing Containerfile instruction, registry access, context files, and storage capacity."])

# 11–15: Kubernetes delivery tools. Context and namespace are always explicit.
kube=["kubectl","--context","$context","--namespace","$namespace"]
conditions={"uid":"metadata.uid","version":"metadata.resourceVersion","generation":"metadata.generation","conditions":"status.conditions.*.type","condition_status":"status.conditions.*.status","reason":"status.conditions.*.reason"}
add("kubernetes","Kubernetes","Kubernetes","One Deployment's desired and available replicas",command=kube+["get","deployment","$resource","-o","json"],fields={**conditions,"desired":"spec.replicas","available":"status.availableReplicas","updated":"status.updatedReplicas","observed":"status.observedGeneration"},rules=[rule("available","less_than_field","desired","Deployment has unavailable replicas","Scheduling, probes, image pulls, crashes, or dependencies may be blocking rollout.",["Inspect ReplicaSets, pod events and node capacity","Check probe failures, image access and referenced Secrets/ConfigMaps","Check Service selectors and disruption budgets before changing anything"]),bad("reason",["ProgressDeadlineExceeded"],"Deployment exceeded its rollout deadline","The new ReplicaSet did not become available in time.",["Inspect the new pod's events and readiness","Compare the new image/configuration with the prior revision"])],repair={"id":"rollout-restart","command":kube+["rollout","restart","deployment/$resource"],"allowed_field":"available","below_field":"desired","verify_field":"available","compare_field":"desired","risk":"Replaces deployment pods and may reduce availability. No automatic rollback; inspect rollout history and disruption policy first.","polls":6})
add("helm","Helm","Kubernetes","Release status and revision",command=["helm","status","$resource","--namespace","$namespace","--kube-context","$context","--output","json"],fields={"release":"name","revision":"version","namespace":"namespace","status":"info.status"},rules=[bad("status",["failed","pending-install","pending-upgrade","pending-rollback"],"Helm release failed or has a pending operation","Hooks, unavailable workloads, timeouts, or interrupted operations may be involved.",["Inspect release history and hook/job status","Confirm no deployment is still in progress","Choose an explicit known-good revision before any rollback"])])
add("kustomize","Kustomize","Kubernetes","Renderability and manifest kind inventory; no manifest bodies retained",command=["kubectl","kustomize","$directory"],parser="manifest",guidance=["This builds local manifests and does not compare them with live cluster state.","Check overlays, resource paths, patches, API versions, and referenced configuration."])
add("argocd","Argo CD","Kubernetes","Application health, sync, and operation phase",command=["argocd","app","get","$resource","--server","$server","--grpc-web","--output","json"],fields={"uid":"metadata.uid","sync":"status.sync.status","health":"status.health.status","phase":"status.operationState.phase","revision":"status.sync.revision"},rules=[bad("health",["Degraded","Missing","Unknown"],"Argo CD application is not healthy","One or more desired resources are absent, failing, or cannot be assessed.",["Inspect the resource tree and controller events","Check source revision and cluster credentials"]),bad("sync",["OutOfSync"],"Desired and live state differ","A Git change or live drift may have occurred.",["Review the diff and ownership before syncing","Check sync policy and excluded resources"])])
add("flux","Flux","Kubernetes","Kustomization readiness and reconciliation revision",command=kube+["get","kustomizations.kustomize.toolkit.fluxcd.io","$resource","-o","json"],fields={**conditions,"revision":"status.lastAppliedRevision","ready":"status.conditions.*.status"},rules=[bad("reason",["ReconciliationFailed","BuildFailed","HealthCheckFailed","ArtifactFailed"],"Flux reconciliation failed","Source artifact, rendering, policy, or workload health may be blocking reconciliation.",["Check the source controller and Kustomization conditions","Fix the Git source or dependency rather than repeatedly forcing reconciliation"])])

# 16–20: CI/CD APIs expose build metadata, not console logs or secrets.
add("jenkins","Jenkins","CI/CD","Latest build metadata for one job",endpoint="/job/$resource/lastBuild/api/json?tree=number,result,building",fields={"number":"number","result":"result","building":"building"},rules=[bad("result",["FAILURE","UNSTABLE","ABORTED"],"Latest Jenkins build did not succeed","A build stage, agent, dependency, timeout, or operator cancellation may be responsible.",["Identify the first failing stage","Inspect redacted console output and agent availability","Check credentials binding and artifact availability before retrying"])])
add("github-actions","GitHub Actions","CI/CD","One workflow run",endpoint="/repos/$owner/$repository/actions/runs/$resource",fields={"id":"id","status":"status","conclusion":"conclusion","sha":"head_sha","attempt":"run_attempt"},rules=[bad("conclusion",["failure","timed_out","action_required","cancelled"],"Workflow run needs investigation","A job failed, timed out, was blocked, or was cancelled.",["Inspect the first failed job and permissions","Check runner availability, artifacts, dependencies and environment approvals"])],repair={"id":"rerun-failed","endpoint":"/repos/$owner/$repository/actions/runs/$resource/rerun-failed-jobs","method":"POST","allowed_field":"conclusion","allowed_values":["failure","timed_out"],"verify_field":"status","verify_values":["queued","in_progress"],"risk":"Reruns failed jobs and their dependents; jobs may deploy or incur costs. Verification confirms scheduling, not successful recovery."})
add("gitlab-ci","GitLab CI/CD","CI/CD","One pipeline's status",endpoint="/api/v4/projects/$project/pipelines/$resource",fields={"id":"id","status":"status","sha":"sha","ref":"ref"},rules=[bad("status",["failed","canceled","blocked"],"GitLab pipeline did not succeed","A job failure, manual gate, cancellation, or runner problem may explain the state.",["Inspect failed jobs and protected-variable access","Check runner tags, protected refs and environment gates"])],repair={"id":"retry-failed","endpoint":"/api/v4/projects/$project/pipelines/$resource/retry","method":"POST","allowed_field":"status","allowed_values":["failed"],"verify_field":"status","verify_values":["pending","running","created"],"risk":"Retries failed/cancelled jobs; deployment jobs may change live systems or incur costs. Verification only confirms scheduling."})
add("azure-pipelines","Azure Pipelines","CI/CD","One Azure DevOps build",endpoint="/$organization/$project/_apis/build/builds/$resource?api-version=7.1",fields={"id":"id","status":"status","result":"result","commit":"sourceVersion"},rules=[bad("result",["failed","partiallySucceeded","canceled"],"Azure pipeline did not fully succeed","Task, agent, service connection, approval, or artifact issues may be involved.",["Inspect stage/task results and agent capabilities","Check service connections, environment approvals and variable scopes"])])
add("tekton","Tekton","CI/CD","PipelineRun conditions",command=kube+["get","pipelineruns.tekton.dev","$resource","-o","json"],fields=conditions,rules=[bad("reason",["Failed","PipelineRunTimeout","TaskRunTimeout","CouldntGetPipeline","InvalidBindings"],"Tekton PipelineRun failed","Task execution, timeouts, missing definitions or bindings may be blocking the run.",["Inspect TaskRuns and pod events","Check workspaces, service accounts and referenced pipeline definitions"])])

# 21–25: infrastructure definitions and deployed stack metadata.
for key,name,binary in (("terraform","Terraform","terraform"),("opentofu","OpenTofu","tofu")):
    add(key,name,"Infrastructure as Code","Local initialized configuration validation; no plan/apply",command=[binary,"validate","-json"],cwd="$directory",ok=(0,1),fields={"valid":"valid","errors":"error_count","warnings":"warning_count","severity":"diagnostics.*.severity","summary":"diagnostics.*.summary"},rules=[bad("valid",[False],"Infrastructure configuration is invalid","Syntax, provider schema, references, or variable declarations may be inconsistent.",["Correct the reported diagnostic summaries","Initialize approved provider versions separately if required","Review a separate plan before any apply"])])
add("pulumi","Pulumi","Infrastructure as Code","Selected stack's resource inventory, excluding outputs and inputs",command=["pulumi","stack","export","--stack","$stack"],cwd="$directory",fields={"resource":"deployment.resources.*.urn","type":"deployment.resources.*.type","pending":"deployment.pending_operations.*.type"},rules=[rule("pending","nonempty",None,"Pulumi stack has pending operations","An update may have been interrupted or is still running.",["Check backend locks and the latest update event log","Reconcile provider state before importing, refreshing or cancelling operations"])])
for key,name in (("cloudformation","AWS CloudFormation"),("cdk","AWS CDK")):
    add(key,name,"Infrastructure as Code","Deployed CloudFormation stack status" if key=="cloudformation" else "CloudFormation status of one deployed CDK stack",command=["aws","--profile","$profile","--region","$region","cloudformation","describe-stacks","--stack-name","$resource","--output","json"],fields={"id":"Stacks.*.StackId","name":"Stacks.*.StackName","status":"Stacks.*.StackStatus"},rules=[bad("status",["CREATE_FAILED","ROLLBACK_FAILED","ROLLBACK_COMPLETE","UPDATE_ROLLBACK_FAILED","DELETE_FAILED"],"Stack operation failed or rolled back","A resource, permission, quota, dependency, or rollback condition may have failed.",["Inspect the earliest failing stack event","Resolve that resource's cause before another update","Check retained resources and drift before recovery"])])

# 26–30: configuration management, with narrow inspection scope.
add("ansible","Ansible","Configuration","Inventory visibility; no playbooks run",command=["ansible-inventory","--inventory","$inventory","--list"],parser="inventory",guidance=["Inventory plugins can contact external inventory providers; use a trusted inventory.","This does not establish host reachability or playbook correctness.","Check group membership, connection variables and privilege escalation policy before a run."])
add("puppet","Puppet","Configuration","One service's observed ensure state",command=["puppet","resource","service","$resource"],parser="puppet",rules=[bad("ensure",["stopped"],"Puppet-observed service is stopped","The daemon may be intentionally stopped or may have failed.",["Compare with the Puppet catalog's intended ensure state","Inspect the service journal and Puppet report before changing the resource"])])
add("chef","Chef","Configuration","One Chef node's last observation time",command=["knife","node","show","$resource","--attribute","ohai_time","--format","json"],fields={"observed":"ohai_time"},guidance=["An old ohai_time may i…2951 tokens truncated…list-versions","--subscription","$subscription","--vault-name","$vault","--name","$resource","--output","json"],fields={"id":"*.id","enabled":"*.attributes.enabled","expires":"*.attributes.expires"},guidance=["Historical versions may intentionally be disabled; compare the consuming application's selected version.","Check identity permissions, network restrictions and expiry without reading secret values."])
add("keycloak","Keycloak","Secrets and access","Management-port readiness",endpoint="/health/ready",health_codes=(200,503),fields={"status":"status","check":"checks.*.name","check_status":"checks.*.status"},rules=[bad("status",["DOWN"],"Keycloak is not ready","Database, initialization, cluster or dependency readiness may be failing.",["Check management health settings and database connectivity","Review startup logs locally and protect authentication data"])])
add("teleport","Teleport","Secrets and access","Proxy web API reachability and version",endpoint="/webapi/ping",fields={"version":"server_version","proxy":"proxy.ssh.public_addr"},guidance=["Proxy API availability does not establish auth-server, node or certificate health.","Check cluster identity, certificate expiry, reverse tunnels and node connectivity through authorized tctl/tsh access."])

# 51–55: networking and traffic management.
add("nginx","NGINX","Networking","Protected stub_status counters",endpoint="/status",parser="nginx",guidance=["Connections alone do not identify upstream errors.","Compare access/error logs, upstream health, TLS expiry, worker limits and configuration syntax locally."])
add("haproxy","HAProxy","Networking","Backend/server states from protected CSV statistics",endpoint="/stats;csv",parser="haproxy",rules=[bad("state",["DOWN","MAINT","NOLB"],"HAProxy reports an unavailable or drained backend","Backend health checks, maintenance state, routing or upstream failures may be involved.",["Inspect affected backend health-check results","Confirm whether maintenance/drain is intentional","Restore upstream health before changing load-balancer state"])])
add("traefik","Traefik","Networking","Router/service overview errors",endpoint="/api/overview",fields={"http_router_errors":"http.routers.errors","http_service_errors":"http.services.errors","tcp_router_errors":"tcp.routers.errors","tcp_service_errors":"tcp.services.errors"},rules=[rule("http_router_errors","gt",0,"Traefik HTTP router configuration has errors","Provider configuration, missing middleware/service references, or invalid routing rules may be involved.",["Inspect the affected router and provider errors","Check entrypoints, service discovery and TLS configuration"])])
add("istio","Istio","Networking","istiod control-plane pod readiness",command=kube+["get","pods","--selector","app=istiod","-o","json"],fields={"pod":"items.*.metadata.name","phase":"items.*.status.phase","ready":"items.*.status.containerStatuses.*.ready","reason":"items.*.status.containerStatuses.*.state.waiting.reason"},rules=[bad("ready",[False],"An Istio control-plane container is not ready","Startup, configuration, certificates, resource limits or control-plane dependencies may be involved.",["Inspect istiod events and redacted logs","Review control-plane version skew and proxy connection status"]),bad("phase",["Failed","Pending","Unknown"],"Istio control-plane pod needs investigation","The control-plane pod may not be scheduled or may have failed.",["Inspect node capacity and pod events before changing mesh configuration"])])
add("envoy","Envoy","Networking","Protected admin readiness",endpoint="/ready",parser="envoy",health_codes=(200,503),rules=[bad("ready",[False],"Envoy is not live","Initialization, listener warming, control-plane connectivity or draining may be involved.",["Inspect listener/cluster warming and xDS connectivity","Check certificates and upstream health; protect the admin interface"])])

# 56–60: databases and messaging. Native credential stores/environment, not argv passwords.
add("postgresql","PostgreSQL","Databases and messaging","Current database connection and recovery metadata",command=["psql","--no-psqlrc","--dbname","service=$service","--csv","--command","SELECT pg_is_in_recovery() AS in_recovery, numbackends, deadlocks FROM pg_stat_database WHERE datname = current_database();"],parser="csv",guidance=["Use a dedicated read-only role via pg_service.conf and pgpass.","Recovery state may be expected on a replica; compare with intended role.","Cumulative deadlocks require time-series comparison; inspect blocking sessions separately."])
add("mysql","MySQL","Databases and messaging","Server read-only mode and configured connection limit",command=["mysql","--defaults-extra-file=$credentials_file","--batch","--execute","SELECT @@read_only AS read_only, @@version AS version, @@max_connections AS max_connections;"],parser="tsv",guidance=["Use a dedicated least-privilege account in the private defaults file.","Read-only mode can be intentional on a replica. Inspect replication and connection pressure before changes."])
add("redis","Redis","Databases and messaging","Memory utilization and eviction policy metadata",command=["redis-cli","--host","$host","--port","$port","--json","INFO","memory"],parser="redis",guidance=["Use REDISCLI_AUTH for authentication and a trusted local/tunneled endpoint; this profile does not configure TLS.","Compare used memory, maxmemory, eviction policy and eviction counters before changing limits."])
add("mongodb","MongoDB","Databases and messaging","Topology role and writable-primary metadata",command=["mongosh","--quiet","--norc","--nodb","--eval","const c=new Mongo(process.env.TRIAGE_MONGODB_URI); print(JSON.stringify(c.getDB('admin').runCommand({hello:1})));"],fields={"ok":"ok","primary":"isWritablePrimary","secondary":"secondary","set":"setName","election":"electionId"},rules=[bad("ok",[0],"MongoDB hello command failed","Connectivity, authorization or server state may be blocking the request.",["Inspect driver connection errors and replica-set health","Verify the configured replica set and authentication source"])],guidance=["Set TRIAGE_MONGODB_URI in the environment; it is never added to argv or reports.","A secondary is not automatically unhealthy; compare with the intended read/write role."])
add("kafka","Apache Kafka","Databases and messaging","One topic's leader and in-sync replica metadata",command=["kafka-topics.sh","--bootstrap-server","$bootstrap","--command-config","$credentials_file","--describe","--topic","$resource"],parser="kafka",rules=[bad("leader",[-1],"Kafka partition has no leader","Broker failure, replica availability or controller issues may block election.",["Inspect broker/controller health and ISR membership","Avoid unclean leader election without understanding data-loss risk"]),rule("under_replicated","in",[True],"Kafka partition is under-replicated","A replica is offline, lagging, or cannot fetch from the leader.",["Inspect broker disk, network and replication lag","Restore replica health before considering reassignment"])])
